"""Sample-level upstream/downstream lineage tracing.

The public entry point is :func:`trace_sample_lineage`. ``samples`` declares
the known samples as ``dataset_id``/``sample_id`` pairs, ``edges`` reuse the
field-level semantics of :func:`data_quality.trace_field_lineage` (directed
edges from ``source`` field to ``target`` field, both declared in ``fields``)
and each edge additionally carries ``witnesses`` listing the sample
references that observe that field-level relationship. ``sample_links`` is
an undirected graph between sample references.

Walking from one sample to another costs one relationship hop: a field edge
may be crossed only when both endpoint samples witness it (the edge's
``witnesses`` match both ``(table, column)`` pairs), and a sample link may
be crossed in either direction. Upstream traversal follows field edges
backwards (and sample links undirected), downstream traversal follows them
forwards (and sample links undirected).

Structure problems raise :class:`InvalidSampleLineageInputError`, bad query
arguments raise :class:`InvalidSampleLineageQueryError`, a target that is
not declared in ``samples`` raises
:class:`UnknownSampleLineageTargetError` and a ``sample_links`` endpoint that
is not declared in ``samples`` raises
:class:`UnknownSampleLineageReferenceError`.
"""

from __future__ import annotations

from collections import deque
from typing import Any, Dict, List, Optional, Set, Tuple

__all__ = [
    "trace_sample_lineage",
    "InvalidSampleLineageInputError",
    "InvalidSampleLineageQueryError",
    "UnknownSampleLineageTargetError",
    "UnknownSampleLineageReferenceError",
]

VALID_DIRECTIONS = ("upstream", "downstream", "both")
_SAMPLE_KEYS = frozenset({"dataset_id", "sample_id"})
_FIELD_KEYS = frozenset({"table", "column"})
_EDGE_KEYS = frozenset({"source", "target", "witnesses"})
_LINK_KEYS = frozenset({"left", "right"})

# A sample is identified by its (dataset_id, sample_id) pair.
SampleId = Tuple[str, str]
# A field is identified by its (table, column) pair.
FieldId = Tuple[str, str]
# A witness is a (sample, field) pair.
WitnessId = Tuple[SampleId, FieldId]


class InvalidSampleLineageInputError(ValueError):
    """The sample lineage input (``samples``/``fields``/``edges``/
    ``sample_links``) is missing or malformed."""


class InvalidSampleLineageQueryError(ValueError):
    """The query arguments (``target``/``direction``/``max_depth``) are bad."""


class UnknownSampleLineageTargetError(LookupError):
    """The queried ``target`` is not declared among ``samples``."""


class UnknownSampleLineageReferenceError(LookupError):
    """A ``sample_links`` endpoint is not declared among ``samples``."""


def _sample_id(endpoint: Dict[str, Any]) -> SampleId:
    return (endpoint["dataset_id"], endpoint["sample_id"])


def _field_id(endpoint: Dict[str, Any]) -> FieldId:
    return (endpoint["table"], endpoint["column"])


def _sample_ref(sample: SampleId) -> Dict[str, str]:
    return {"dataset_id": sample[0], "sample_id": sample[1]}


def _validate_samples(samples: Any) -> Set[SampleId]:
    if not isinstance(samples, list):
        raise InvalidSampleLineageInputError("samples must be a list")

    declared: Set[SampleId] = set()
    for index, sample in enumerate(samples):
        if not isinstance(sample, dict):
            raise InvalidSampleLineageInputError(
                f"samples[{index}] must be an object"
            )
        keys = set(sample)
        if keys != _SAMPLE_KEYS:
            missing = sorted(_SAMPLE_KEYS - keys)
            if missing:
                raise InvalidSampleLineageInputError(
                    f"samples[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - _SAMPLE_KEYS)
            raise InvalidSampleLineageInputError(
                f"samples[{index}] has unsupported keys: {unknown}"
            )
        dataset = sample["dataset_id"]
        sample_key = sample["sample_id"]
        if not isinstance(dataset, str) or not dataset:
            raise InvalidSampleLineageInputError(
                f"samples[{index}].dataset_id must be a non-empty string"
            )
        if not isinstance(sample_key, str) or not sample_key:
            raise InvalidSampleLineageInputError(
                f"samples[{index}].sample_id must be a non-empty string"
            )
        ref = (dataset, sample_key)
        if ref in declared:
            raise InvalidSampleLineageInputError(
                f"duplicate sample: {sample!r}"
            )
        declared.add(ref)
    return declared


def _validate_fields(fields: Any) -> Set[FieldId]:
    if not isinstance(fields, dict):
        raise InvalidSampleLineageInputError(
            "fields must be an object mapping table ids to field id lists"
        )

    declared: Set[FieldId] = set()
    for table, columns in fields.items():
        if not isinstance(table, str) or not table:
            raise InvalidSampleLineageInputError(
                f"fields key must be a non-empty table id string: {table!r}"
            )
        if not isinstance(columns, list):
            raise InvalidSampleLineageInputError(
                f"fields[{table!r}] must be a list of field ids"
            )
        seen_columns: Set[str] = set()
        for index, column in enumerate(columns):
            if not isinstance(column, str) or not column:
                raise InvalidSampleLineageInputError(
                    f"fields[{table!r}][{index}] must be a non-empty "
                    "field id string"
                )
            if column in seen_columns:
                raise InvalidSampleLineageInputError(
                    f"duplicate field id in table {table!r}: {column!r}"
                )
            seen_columns.add(column)
            declared.add((table, column))
    return declared


def _check_field_endpoint(
    endpoint: Any, declared: Set[FieldId], where: str
) -> FieldId:
    if not isinstance(endpoint, dict):
        raise InvalidSampleLineageInputError(f"{where} must be an object")
    keys = set(endpoint)
    if keys != _FIELD_KEYS:
        missing = sorted(_FIELD_KEYS - keys)
        if missing:
            raise InvalidSampleLineageInputError(
                f"{where} is missing keys: {missing}"
            )
        unknown = sorted(keys - _FIELD_KEYS)
        raise InvalidSampleLineageInputError(
            f"{where} has unsupported keys: {unknown}"
        )
    table = endpoint["table"]
    column = endpoint["column"]
    if not isinstance(table, str) or not table:
        raise InvalidSampleLineageInputError(
            f"{where}.table must be a non-empty string"
        )
    if not isinstance(column, str) or not column:
        raise InvalidSampleLineageInputError(
            f"{where}.column must be a non-empty string"
        )
    field = (table, column)
    if field not in declared:
        raise InvalidSampleLineageInputError(
            f"{where} is not a declared field: {endpoint!r}"
        )
    return field


def _validate_witnesses(
    witnesses: Any,
    index: int,
    declared_samples: Set[SampleId],
    declared_fields: Set[FieldId],
) -> List[Tuple[SampleId, FieldId]]:
    if not isinstance(witnesses, list):
        raise InvalidSampleLineageInputError(
            f"edges[{index}].witnesses must be a list"
        )

    where = f"edges[{index}].witnesses"
    seen: Set[WitnessId] = set()
    result: List[Tuple[SampleId, FieldId]] = []
    for witness_index, witness in enumerate(witnesses):
        witness_where = f"{where}[{witness_index}]"
        if not isinstance(witness, dict):
            raise InvalidSampleLineageInputError(
                f"{witness_where} must be an object"
            )
        keys = set(witness)
        expected = _SAMPLE_KEYS | _FIELD_KEYS
        if keys != expected:
            missing = sorted(expected - keys)
            if missing:
                raise InvalidSampleLineageInputError(
                    f"{witness_where} is missing keys: {missing}"
                )
            unknown = sorted(keys - expected)
            raise InvalidSampleLineageInputError(
                f"{witness_where} has unsupported keys: {unknown}"
            )
        for key in ("dataset_id", "sample_id", "table", "column"):
            value = witness[key]
            if not isinstance(value, str) or not value:
                raise InvalidSampleLineageInputError(
                    f"{witness_where}.{key} must be a non-empty string"
                )
        sample = (witness["dataset_id"], witness["sample_id"])
        field = (witness["table"], witness["column"])
        if sample not in declared_samples:
            raise InvalidSampleLineageInputError(
                f"{witness_where} is not a declared sample: "
                f"{_sample_ref(sample)!r}"
            )
        if field not in declared_fields:
            raise InvalidSampleLineageInputError(
                f"{witness_where} is not a declared field: {witness!r}"
            )
        pair = (sample, field)
        if pair in seen:
            raise InvalidSampleLineageInputError(
                f"duplicate witness in edges[{index}]: {witness!r}"
            )
        seen.add(pair)
        result.append(pair)
    return result


def _validate_edges(
    edges: Any,
    declared_samples: Set[SampleId],
    declared_fields: Set[FieldId],
) -> List[Dict[str, Any]]:
    if not isinstance(edges, list):
        raise InvalidSampleLineageInputError("edges must be a list")

    seen_edges: Set[Tuple[FieldId, FieldId]] = set()
    validated: List[Dict[str, Any]] = []
    for index, edge in enumerate(edges):
        if not isinstance(edge, dict):
            raise InvalidSampleLineageInputError(
                f"edges[{index}] must be an object"
            )
        keys = set(edge)
        if keys != _EDGE_KEYS:
            missing = sorted(_EDGE_KEYS - keys)
            if missing:
                raise InvalidSampleLineageInputError(
                    f"edges[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - _EDGE_KEYS)
            raise InvalidSampleLineageInputError(
                f"edges[{index}] has unsupported keys: {unknown}"
            )

        source = _check_field_endpoint(
            edge["source"], declared_fields, f"edges[{index}].source"
        )
        target = _check_field_endpoint(
            edge["target"], declared_fields, f"edges[{index}].target"
        )
        witnesses = _validate_witnesses(
            edge["witnesses"], index, declared_samples, declared_fields
        )

        pair = (source, target)
        if pair in seen_edges:
            raise InvalidSampleLineageInputError(
                f"duplicate edge: {edge['source']!r} -> {edge['target']!r}"
            )
        seen_edges.add(pair)
        validated.append(
            {
                "source": source,
                "target": target,
                "source_ref": edge["source"],
                "target_ref": edge["target"],
                "witnesses": witnesses,
                "original": edge,
            }
        )
    return validated


def _validate_sample_links(
    sample_links: Any, declared_samples: Set[SampleId]
) -> List[Tuple[SampleId, SampleId]]:
    """Validate the undirected sample link graph.

    Structure problems (not a list, missing/extra keys, empty identifiers,
    self links, duplicate relationships including reversed ones) raise
    :class:`InvalidSampleLineageInputError` and take precedence over
    :class:`UnknownSampleLineageReferenceError`, raised when an endpoint is
    not declared in ``samples``.
    """
    if not isinstance(sample_links, list):
        raise InvalidSampleLineageInputError("sample_links must be a list")

    pairs: List[Tuple[SampleId, SampleId]] = []
    for index, link in enumerate(sample_links):
        if not isinstance(link, dict):
            raise InvalidSampleLineageInputError(
                f"sample_links[{index}] must be an object"
            )
        keys = set(link)
        if keys != _LINK_KEYS:
            missing = sorted(_LINK_KEYS - keys)
            if missing:
                raise InvalidSampleLineageInputError(
                    f"sample_links[{index}] is missing keys: {missing}"
                )
            unknown = sorted(keys - _LINK_KEYS)
            raise InvalidSampleLineageInputError(
                f"sample_links[{index}] has unsupported keys: {unknown}"
            )
        left = _check_link_endpoint(link["left"], f"sample_links[{index}].left")
        right = _check_link_endpoint(
            link["right"], f"sample_links[{index}].right"
        )
        pairs.append((left, right))

    seen_relations: Set[frozenset] = set()
    for left, right in pairs:
        if left == right:
            raise InvalidSampleLineageInputError(
                f"sample link connects a sample to itself: "
                f"{_sample_ref(left)!r}"
            )
        relation = frozenset((left, right))
        if relation in seen_relations:
            raise InvalidSampleLineageInputError(
                f"duplicate sample link between {_sample_ref(left)!r} and "
                f"{_sample_ref(right)!r}"
            )
        seen_relations.add(relation)

    for left, right in pairs:
        for endpoint in (left, right):
            if endpoint not in declared_samples:
                raise UnknownSampleLineageReferenceError(
                    "sample link endpoint is not a declared sample: "
                    f"{_sample_ref(endpoint)!r}"
                )
    return pairs


def _check_link_endpoint(endpoint: Any, where: str) -> SampleId:
    if not isinstance(endpoint, dict):
        raise InvalidSampleLineageInputError(f"{where} must be an object")
    keys = set(endpoint)
    if keys != _SAMPLE_KEYS:
        missing = sorted(_SAMPLE_KEYS - keys)
        if missing:
            raise InvalidSampleLineageInputError(
                f"{where} is missing keys: {missing}"
            )
        unknown = sorted(keys - _SAMPLE_KEYS)
        raise InvalidSampleLineageInputError(
            f"{where} has unsupported keys: {unknown}"
        )
    dataset = endpoint["dataset_id"]
    sample = endpoint["sample_id"]
    if not isinstance(dataset, str) or not dataset:
        raise InvalidSampleLineageInputError(
            f"{where}.dataset_id must be a non-empty string"
        )
    if not isinstance(sample, str) or not sample:
        raise InvalidSampleLineageInputError(
            f"{where}.sample_id must be a non-empty string"
        )
    return (dataset, sample)


def _validate_query(target: Any, direction: Any, max_depth: Any) -> SampleId:
    if not isinstance(target, dict):
        raise InvalidSampleLineageQueryError(
            "target must be an object with 'dataset_id' and 'sample_id'"
        )
    keys = set(target)
    if keys != _SAMPLE_KEYS:
        missing = sorted(_SAMPLE_KEYS - keys)
        if missing:
            raise InvalidSampleLineageQueryError(
                f"target is missing keys: {missing}"
            )
        unknown = sorted(keys - _SAMPLE_KEYS)
        raise InvalidSampleLineageQueryError(
            f"target has unsupported keys: {unknown}"
        )
    if not isinstance(target["dataset_id"], str) or not target["dataset_id"]:
        raise InvalidSampleLineageQueryError(
            "target.dataset_id must be a non-empty string"
        )
    if not isinstance(target["sample_id"], str) or not target["sample_id"]:
        raise InvalidSampleLineageQueryError(
            "target.sample_id must be a non-empty string"
        )
    if direction not in VALID_DIRECTIONS:
        raise InvalidSampleLineageQueryError(
            f"direction must be one of {list(VALID_DIRECTIONS)}, "
            f"got {direction!r}"
        )
    if max_depth is not None:
        # bool is a subclass of int, but JSON true/false are not depths.
        if isinstance(max_depth, bool) or not isinstance(max_depth, int):
            raise InvalidSampleLineageQueryError(
                "max_depth must be null or an integer >= 0"
            )
        if max_depth < 0:
            raise InvalidSampleLineageQueryError(
                f"max_depth must be >= 0, got {max_depth}"
            )
    return _sample_id(target)


def _build_adjacency(
    edges: List[Dict[str, Any]],
    links: List[Tuple[SampleId, SampleId]],
) -> Tuple[
    Dict[SampleId, List[Tuple[str, Any]]],
    Dict[SampleId, List[Tuple[str, Any]]],
]:
    """Build downstream and upstream sample adjacency.

    A field edge may be crossed between two samples only when both samples
    witness the edge's source field and its target field, i.e. the edge's
    ``witnesses`` contain both the ``(sample, source_field)`` and
    ``(sample, target_field)`` pairs for each endpoint sample. Every such
    crossing is one relationship hop; each sample link is one hop in both
    directions.

    Neighbours are ``(kind, payload)`` pairs where ``kind`` is ``"edge"``
    (payload is the validated edge dict) or ``"link"`` (payload is the
    ``(left, right)`` link tuple).
    """
    downstream: Dict[SampleId, List[Tuple[str, Any]]] = {}
    upstream: Dict[SampleId, List[Tuple[str, Any]]] = {}

    for edge in edges:
        source = edge["source"]
        target = edge["target"]
        witness_samples: Dict[SampleId, Set[FieldId]] = {}
        for sample, field in edge["witnesses"]:
            witness_samples.setdefault(sample, set()).add(field)
        matched = [
            sample
            for sample, fields in witness_samples.items()
            if source in fields and target in fields
        ]
        for sample_a in matched:
            for sample_b in matched:
                if sample_a == sample_b:
                    continue
                # Forward: source sample -> target sample.
                downstream.setdefault(sample_a, []).append(("edge", edge))
                downstream.setdefault(sample_b, [])
                # Backward: target sample -> source sample.
                upstream.setdefault(sample_b, []).append(("edge", edge))
                upstream.setdefault(sample_a, [])

    for left, right in links:
        downstream.setdefault(left, []).append(("link", (left, right)))
        downstream.setdefault(right, []).append(("link", (left, right)))
        upstream.setdefault(left, []).append(("link", (left, right)))
        upstream.setdefault(right, []).append(("link", (left, right)))

    return downstream, upstream


def _walk(
    start: SampleId,
    neighbors: Dict[SampleId, List[Tuple[str, Any]]],
    max_depth: Optional[int],
) -> Tuple[Dict[SampleId, int], Set[Any]]:
    """BFS from ``start``; first visit wins, so depths are shortest.

    Returns the shortest depth of every reached sample and the set of
    relationships (validated edge dicts / link tuples) usable along the way
    whose both endpoint samples were reached.
    """
    depths = {start: 0}
    used: Set[Any] = set()
    if max_depth == 0:
        return depths, used

    queue = deque([(start, 0)])
    while queue:
        sample, depth = queue.popleft()
        if max_depth is not None and depth >= max_depth:
            continue
        next_depth = depth + 1
        for kind, payload in neighbors.get(sample, ()):
            if kind == "edge":
                edge = payload
                source = edge["source"]
                target = edge["target"]
                witness_samples: Dict[SampleId, Set[FieldId]] = {}
                for witness_sample, field in edge["witnesses"]:
                    witness_samples.setdefault(witness_sample, set()).add(field)
                matched = {
                    witness_sample
                    for witness_sample, fields in witness_samples.items()
                    if source in fields and target in fields
                }
                nxt = None
                # Downstream walk: sample currently at the edge's source
                # field moves to a sample at the target field; upstream is
                # the mirror image.
                fields_of_current = witness_samples.get(sample, set())
                going_downstream = source in fields_of_current
                for candidate in matched:
                    candidate_fields = witness_samples[candidate]
                    if going_downstream:
                        if target in candidate_fields:
                            nxt = candidate
                            break
                    else:
                        if source in candidate_fields:
                            nxt = candidate
                            break
            else:
                left, right = payload
                nxt = right if sample == left else left

            if nxt is not None and nxt not in depths:
                depths[nxt] = next_depth
                queue.append((nxt, next_depth))
    return depths, used


def _walk_side(
    start: SampleId,
    edges: List[Dict[str, Any]],
    links: List[Tuple[SampleId, SampleId]],
    direction: str,
    max_depth: Optional[int],
) -> Dict[SampleId, int]:
    """BFS over samples for one direction.

    ``direction`` is ``"downstream"`` (field edges forward, links either
    way) or ``"upstream"`` (field edges backward, links either way).
    """
    depths = {start: 0}
    if max_depth == 0:
        return depths

    # Precompute, per field edge, the samples witnessing both endpoints.
    edge_matches: List[Tuple[Dict[str, Any], Set[SampleId]]] = []
    for edge in edges:
        by_sample: Dict[SampleId, Set[FieldId]] = {}
        for sample, field in edge["witnesses"]:
            by_sample.setdefault(sample, set()).add(field)
        matched = {
            sample
            for sample, fields in by_sample.items()
            if edge["source"] in fields and edge["target"] in fields
        }
        edge_matches.append((edge, matched))

    link_neighbours: Dict[SampleId, Set[SampleId]] = {}
    for left, right in links:
        link_neighbours.setdefault(left, set()).add(right)
        link_neighbours.setdefault(right, set()).add(left)

    queue = deque([(start, 0)])
    while queue:
        sample, depth = queue.popleft()
        if max_depth is not None and depth >= max_depth:
            continue
        next_depth = depth + 1

        for other in link_neighbours.get(sample, ()):  # undirected links
            if other not in depths:
                depths[other] = next_depth
                queue.append((other, next_depth))

        for edge, matched in edge_matches:
            if sample not in matched:
                continue
            for other in matched:
                if other == sample or other in depths:
                    continue
                depths[other] = next_depth
                queue.append((other, next_depth))
    return depths


def _side_edges(
    depths: Dict[SampleId, int],
    edges: List[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Original field edges usable between reached samples, with witnesses.

    An edge belongs to the side when at least one reached pair of distinct
    samples can cross it: both samples witness the edge's source and target
    fields. Returned edge objects keep the original ``source``/``target``
    references and a ``witnesses`` list restricted to the witnesses that
    match the edge's ``(table, column)`` pairs, sorted by sample reference.
    """
    side_edges: List[Dict[str, Any]] = []
    for edge in edges:
        by_sample: Dict[SampleId, Set[FieldId]] = {}
        matched_witnesses: Dict[SampleId, List[Dict[str, Any]]] = {}
        for witness_sample, field in edge["witnesses"]:
            by_sample.setdefault(witness_sample, set()).add(field)
            if field in (edge["source"], edge["target"]):
                matched_witnesses.setdefault(witness_sample, []).append(
                    {
                        "dataset_id": witness_sample[0],
                        "sample_id": witness_sample[1],
                        "table": field[0],
                        "column": field[1],
                    }
                )
        matched_samples = [
            sample
            for sample in by_sample
            if edge["source"] in by_sample[sample]
            and edge["target"] in by_sample[sample]
            and sample in depths
        ]
        if len(matched_samples) < 2:
            continue

        witnesses: List[Dict[str, Any]] = []
        for sample in matched_samples:
            witnesses.extend(matched_witnesses.get(sample, []))
        witnesses.sort(
            key=lambda witness: (
                witness["dataset_id"],
                witness["sample_id"],
                witness["table"],
                witness["column"],
            )
        )
        side_edges.append(
            {
                "source": edge["source_ref"],
                "target": edge["target_ref"],
                "witnesses": witnesses,
                "_edge": edge,
            }
        )

    side_edges.sort(
        key=lambda item: (
            item["source"]["table"],
            item["source"]["column"],
            item["target"]["table"],
            item["target"]["column"],
        )
    )
    for item in side_edges:
        item.pop("_edge")
    return side_edges


def trace_sample_lineage(
    samples: Any,
    fields: Any,
    edges: Any,
    sample_links: Any,
    target: Any,
    direction: Any = "both",
    max_depth: Any = None,
) -> Dict[str, Any]:
    """Trace sample-level upstream/downstream lineage of ``target``.

    :param samples: list of distinct ``{"dataset_id", "sample_id"}`` objects
        with non-empty string values.
    :param fields: object mapping non-empty table ids to lists of distinct
        non-empty field ids, as in :func:`data_quality.trace_field_lineage`.
    :param edges: list of ``{"source", "target", "witnesses"}`` objects;
        ``source``/``target`` are declared ``{"table", "column"}`` fields and
        the edge runs from source to target. ``witnesses`` is a list of
        distinct ``{"dataset_id", "sample_id", "table", "column"}`` objects
        referencing declared samples and fields; a sample may cross the edge
        only when it witnesses both the source and the target field.
        Duplicate edges are rejected; self-loops and cycles are legal.
    :param sample_links: undirected list of ``{"left", "right"}`` links whose
        endpoints are ``{"dataset_id", "sample_id"}`` objects; self links
        and duplicate (including reversed) links are rejected and every
        endpoint must be declared in ``samples``.
    :param target: ``{"dataset_id", "sample_id"}`` sample to trace from;
        depth 0 in every returned side.
    :param direction: ``"upstream"``, ``"downstream"`` or ``"both"``
        (default ``"both"``).
    :param max_depth: ``None`` for unlimited (default) or an integer ``>= 0``;
        ``0`` returns only ``target``. Booleans are not integers here.
    :returns: ``{"target", "direction", "max_depth",
        "upstream": {"samples", "edges"}, "downstream": {"samples",
        "edges"}}``. Each populated side lists samples as
        ``{"dataset_id", "sample_id", "depth"}`` sorted by
        ``(depth, dataset_id, sample_id)`` and includes the field edges
        usable between reached samples as ``{"source", "target",
        "witnesses"}`` sorted by the source/target field references;
        ``witnesses`` only lists witnesses matching the edge's
        ``(table, column)`` pairs, sorted by sample reference. The side not
        queried is returned empty.
    :raises ValueError: :class:`InvalidSampleLineageInputError` or
        :class:`InvalidSampleLineageQueryError`.
    :raises LookupError: :class:`UnknownSampleLineageTargetError` or
        :class:`UnknownSampleLineageReferenceError`.
    """
    declared_samples = _validate_samples(samples)
    declared_fields = _validate_fields(fields)
    validated_edges = _validate_edges(
        edges, declared_samples, declared_fields
    )
    links = _validate_sample_links(sample_links, declared_samples)
    start = _validate_query(target, direction, max_depth)

    if start not in declared_samples:
        raise UnknownSampleLineageTargetError(
            f"target is not declared in samples: {target!r}"
        )

    upstream_depths: Optional[Dict[SampleId, int]] = None
    downstream_depths: Optional[Dict[SampleId, int]] = None
    if direction in ("upstream", "both"):
        upstream_depths = _walk_side(
            start, validated_edges, links, "upstream", max_depth
        )
    if direction in ("downstream", "both"):
        downstream_depths = _walk_side(
            start, validated_edges, links, "downstream", max_depth
        )

    return {
        "target": target,
        "direction": direction,
        "max_depth": max_depth,
        "upstream": _side(upstream_depths, validated_edges),
        "downstream": _side(downstream_depths, validated_edges),
    }


def _side(
    depths: Optional[Dict[SampleId, int]],
    edges: List[Dict[str, Any]],
) -> Dict[str, Any]:
    if depths is None:
        return {"samples": [], "edges": []}

    side_samples = [
        {"dataset_id": dataset, "sample_id": sample, "depth": depth}
        for (dataset, sample), depth in sorted(
            depths.items(), key=lambda item: (item[1], item[0][0], item[0][1])
        )
    ]
    return {"samples": side_samples, "edges": _side_edges(depths, edges)}

